// PERSONAL RESEARCH ONLY: fixed 1/2/3/5% comparisons, 15% daily, 60% peak, 50% entry margin. No production changes.
// Frozen existing Gold Standard production-entry screening, derived from gold-micro/ticks.cpp.
// Not production execution. Explicit 1.5/8 qualification and 4/18 Standard-limit cases; 20% entry margin.
#include <algorithm>
#include <cmath>
#include <vector>
struct Arm{int candidate,side=0,pending=0,minute=-1,day=-1,pendingIndex=0,watchSide=0;double dailyLimit=1.5,peakLimit=8,risk,lev,comm,slip,delay,manage,capital,sampleMs=0,lastClient=-1,bal,eq,peak,dd=0,maxMargin=0,dayStart,gain=0,loss=0,costs=0,entry=0,stop=0,target=0,qty=0,opened=0,entryRisk=0,fees=0,best=0,lastImprove=0,exitAt=-1,pendingAt=0,pendingUntil=0,stopDue=0,proposedStop=0,exitDue=0;int entries=0,closed=0,wins=0,blocked=0;bool locked=false,failed=false,attempted=false;double watchLow=0,watchHigh=0,lowAt=-1,highAt=-1,crossSince=-1,pendingStop=0,pendingReference=0,pendingTarget=0,lastLevel=0,lastLevelAt=-1;int lastLevelSide=0,exitStyle=0,pendingExitStyle=0;std::vector<double>trades;};
struct Engine{int candidates,minutes,index=-1;const double*t,*atr,*level,*ref,*cfg;const signed char*sig;double lastTime=-1,lastBid=0,lastAsk=0;std::vector<Arm>a;};
static double roundp(double p,bool buy){return (buy?std::ceil(p*100-1e-8):std::floor(p*100+1e-8))/100;}
static void finish(Arm&a,double px,double t,int reason){px=roundp(px-a.side*a.slip,a.side<0);double fee=a.qty*a.comm,net=a.side*(px-a.entry)*a.qty*100-a.fees-fee;a.bal+=a.side*(px-a.entry)*a.qty*100-fee;a.costs+=fee;a.gain+=std::max(0.,net);a.loss-=std::min(0.,net);a.wins+=net>0;a.trades.insert(a.trades.end(),{a.opened,t,double(a.side),a.entry,px,a.qty,net,net/a.entryRisk,double(reason),a.entryRisk,a.best,(t-a.opened)/60000});a.closed++;a.side=0;a.pending=0;a.stopDue=0;a.exitDue=0;a.exitAt=t;a.eq=a.bal;a.peak=std::max(a.peak,a.eq);a.dd=std::max(a.dd,(a.peak-a.eq)/a.peak*100);if(a.eq<=a.peak-a.peak*a.peakLimit/100)a.failed=true;}
extern "C" void* micro_create(int candidates,int arms,int minutes,const double*t,const signed char*sig,const double*atr,const double*level,const double*reference,const double*cfg,const double*spec){auto*e=new Engine{candidates,minutes,-1,t,atr,level,reference,cfg,sig};for(int j=0;j<arms;j++){const double*s=spec+j*10;Arm a;a.candidate=int(s[0]);a.risk=s[1];a.lev=s[2];a.comm=s[3];a.slip=s[4];a.delay=s[5];a.manage=s[6];a.capital=s[7];a.sampleMs=s[8];a.bal=a.eq=a.peak=a.dayStart=a.capital;if(a.candidate<0||a.candidate>=candidates||a.risk<=0||a.risk>5||a.lev<=0||a.lev>100||a.comm<0||a.slip<0||a.delay<0||a.manage<0){delete e;return nullptr;}a.dailyLimit=15;a.peakLimit=60;e->a.push_back(a);}return e;}
extern "C" int micro_ticks(void*ptr,int count,const double*time,const double*bid,const double*ask){auto&e=*static_cast<Engine*>(ptr);for(int j=0;j<count;j++){double t=time[j],b=bid[j],s=ask[j];if(!std::isfinite(t)||!std::isfinite(b)||!std::isfinite(s)||b<=0||s<b||t<e.lastTime)return -1;while(e.index+1<e.minutes&&e.t[e.index+1]<=t)e.index++;double quoteGap=e.lastTime<0?0:t-e.lastTime;e.lastTime=t;e.lastBid=b;e.lastAsk=s;if(e.index<0)continue;int mi=e.index,day=int(t/86400000),hour=int(std::fmod(t,86400000)/3600000);
 for(auto&a:e.a){int k=mi*e.candidates+a.candidate;const double*c=e.cfg+a.candidate*6;bool clientDue=a.lastClient<0||t-a.lastClient>=a.sampleMs;if(clientDue)a.lastClient=t;int style=a.exitStyle;int session=int(c[4]),clockMinute=int(std::fmod(t,86400000)/60000);bool active=true;if(a.day!=day){a.day=day;a.dayStart=a.bal+(a.side?a.side*((a.side>0?b:s)-a.entry)*a.qty*100:0);a.locked=false;}
  if(a.side){double px=a.side>0?b:s,dist=a.entryRisk/(a.qty*100);if(a.side*(px-a.stop)<=0)finish(a,px,t,1);else if(a.side*(px-a.target)>=0)finish(a,a.target,t,2);else if(a.stopDue&&t>=a.stopDue){double p=a.proposedStop;a.stopDue=0;if(a.side*(px-p)<=0){if(a.sampleMs>0)a.exitDue=t+a.sampleMs+a.manage;else finish(a,px,t,8);}else a.stop=p;}
   if(a.side){px=a.side>0?b:s;if(a.exitDue&&t>=a.exitDue)finish(a,px,t,3);else if(clientDue){double favorable=a.side*(px-a.entry);if(favorable>a.best+.05*dist){a.best=favorable;a.lastImprove=t;}
    if((t-a.opened>=c[2]*60000||!active)&&!a.exitDue)a.exitDue=t+a.manage;
    if(style==1&&t-a.lastImprove>=180000&&favorable>=.25*dist&&!a.exitDue)a.exitDue=t+a.manage;
    if((style==2&&a.best>=.75*dist||style==3&&a.best>=1.25*dist)&&!a.stopDue&&std::isfinite(e.atr[k])){double lock=std::max(style==3?.5*dist:a.best>=1.2*dist?.4*dist:.1*dist,2*a.comm/100+a.slip+.05*dist),p=a.entry+a.side*std::max(lock,a.best-(style==3?1.25:.75)*e.atr[k]);p=roundp(p,a.side<0);if(a.side*(p-a.stop)>.009){a.proposedStop=p;a.stopDue=t+a.manage;}}
   }}
  }
  bool first=clientDue&&a.minute!=mi;if(first){a.minute=mi;a.attempted=false;a.watchLow=b;a.watchHigh=s;a.lowAt=a.highAt=-1;a.crossSince=-1;a.watchSide=0;}if(quoteGap>5000)a.crossSince=-1;
  if(clientDue&&!a.side&&!a.pending&&!a.attempted&&e.sig[k]&&active&&!a.locked&&!a.failed&&t-a.exitAt>=(int(c[5])==3?300000:60000)){int mode=int(c[5]),desired=0;double st=e.level[k],reference=e.ref[k],av=e.atr[k];if(mode==0&&first&&t-e.t[mi]<=30000)desired=e.sig[k];
   if(mode==1){int side=e.sig[k]==3?1:e.sig[k]==-3?-1:e.sig[k];if(side>0?b>=reference:s<=reference)desired=side;}
   if(mode==2&&std::isfinite(av)){if(first||b<a.watchLow){a.watchLow=b;if(b<e.level[k]-.05*av)a.lowAt=t;}if(first||s>a.watchHigh){a.watchHigh=s;if(s>e.ref[k]+.05*av)a.highAt=t;}
    bool buy=(e.sig[k]==1||e.sig[k]==2)&&a.lowAt>=0&&b>e.level[k]+.05*av&&b-a.watchLow>=.3*av,sell=(e.sig[k]==-1||e.sig[k]==2)&&a.highAt>=0&&s<e.ref[k]-.05*av&&a.watchHigh-s>=.3*av;
    if(buy&&(!sell||a.lowAt>a.highAt)){desired=1;st=a.watchLow-.1*av;reference=b;}else if(sell&&(!buy||a.highAt>a.lowAt)){desired=-1;st=a.watchHigh+.1*av;reference=s;}
   }
   if(mode==3&&std::isfinite(av)){int side=e.sig[k];if(first||b<a.watchLow){a.watchLow=b;if(side==1&&b<e.level[k]-.1*av)a.lowAt=t;}if(first||s>a.watchHigh){a.watchHigh=s;if(side==-1&&s>e.level[k]+.1*av)a.highAt=t;}
    if(side==1&&a.lowAt>=0&&b>e.level[k]+.05*av&&b-a.watchLow>=.5*av){desired=1;st=a.watchLow-.1*av;reference=b;}
    if(side==-1&&a.highAt>=0&&s<e.level[k]-.05*av&&a.watchHigh-s>=.5*av){desired=-1;st=a.watchHigh+.1*av;reference=s;}
    if(desired==a.lastLevelSide&&std::abs(e.level[k]-a.lastLevel)<.5*av&&t-a.lastLevelAt<900000)desired=0;
   }
   if(!desired){a.crossSince=-1;a.watchSide=0;}else{if(a.watchSide!=desired||a.crossSince<0){a.watchSide=desired;a.crossSince=t;}if(mode==0||t-a.crossSince>=250){double spread=s-b,planEntry=mode==0?(reference+(desired>0?spread:0)+desired*a.slip):(reference+desired*(spread+a.slip));double planStop=st;planStop=roundp(planStop,desired<0);double planDistance=desired*(planEntry-planStop),planTarget=reference+desired*std::abs(reference-st)*c[1];if(!std::isfinite(planDistance)||planDistance<=0){a.attempted=true;a.blocked++;continue;}if(mode==3){double meanTarget=e.ref[k]-desired*.1*av;if(desired*(meanTarget-planEntry)<planDistance+spread+2*a.slip+2*a.comm/100){a.attempted=true;a.blocked++;continue;}planTarget=planEntry+desired*std::min(planDistance*c[1],desired*(meanTarget-planEntry));}a.pending=desired;a.pendingIndex=k;a.pendingStop=planStop;a.pendingReference=reference;a.pendingTarget=planTarget;a.pendingExitStyle=int(c[3])==4?(std::abs(int(e.sig[k]))==3?1:3):int(c[3]);if(mode==3){a.lastLevel=e.level[k];a.lastLevelSide=desired;a.lastLevelAt=t;}a.pendingAt=t+a.delay;a.pendingUntil=t+2000;a.attempted=true;}}
  }
  if(a.pending&&!a.side&&t>=a.pendingAt){int side=a.pending,pk=a.pendingIndex;a.pending=0;if(t>a.pendingUntil||quoteGap>3000||!active||a.locked||a.failed){a.blocked++;continue;}double px=roundp((side>0?s:b)+side*a.slip,side>0),at=e.atr[pk],st=a.pendingStop;st=roundp(st,side<0);double dist=side*(px-st),planned=a.pendingTarget,expense=s-b+2*a.slip+2*a.comm/100;if(!std::isfinite(dist)||dist<.10||dist>10*at||side*(planned-px)<.10||s-b>.2*at||expense>.25*dist||side*(px-a.pendingReference)>.25*dist){a.blocked++;continue;}double dailyPct=a.dailyLimit,totalPct=a.peakLimit,room=std::min(a.dayStart*dailyPct/100-(a.dayStart-a.bal),a.peak*totalPct/100-(a.peak-a.bal));double budget=std::min(a.bal*a.risk/100,std::max(0.,room-a.comm*.01)),q=std::floor(std::min(budget/(dist*100+2*a.comm+100*a.slip),a.bal*a.lev*.50/(px*100))*100)/100;if(q<.01||q*px*100/a.lev+q*a.comm>a.bal*.50){a.blocked++;continue;}a.side=side;a.entry=px;a.stop=st;a.target=planned;a.exitStyle=a.pendingExitStyle;a.qty=q;a.opened=t;a.entryRisk=q*100*dist;a.fees=q*a.comm;a.bal-=a.fees;a.costs+=a.fees;a.best=0;a.lastImprove=t;a.entries++;}
  a.eq=a.bal+(a.side?a.side*((a.side>0?b:s)-a.entry)*a.qty*100:0);if(a.side&&a.eq>0)a.maxMargin=std::max(a.maxMargin,100*(a.qty*100*(b+s)/2/a.lev)/a.eq);a.peak=std::max(a.peak,a.eq);a.dd=std::max(a.dd,(a.peak-a.eq)/a.peak*100);double dailyPct=a.dailyLimit,totalPct=a.peakLimit;if(a.eq<=a.dayStart-a.dayStart*dailyPct/100)a.locked=true;if(a.eq<=a.peak-a.peak*totalPct/100)a.failed=true;if(a.locked||a.failed){a.pending=0;if(a.side&&!a.exitDue)a.exitDue=t+a.manage;}
 }
}return 0;}
extern "C" int micro_summary(void*ptr,int arm,double*out,bool close){auto&e=*static_cast<Engine*>(ptr);if(arm<0||arm>=int(e.a.size()))return -1;auto&a=e.a[arm];if(close&&a.side)finish(a,a.side>0?e.lastBid:e.lastAsk,e.lastTime,7);out[0]=a.bal;out[1]=a.eq;out[2]=a.dd;out[3]=a.gain;out[4]=a.loss;out[5]=a.closed;out[6]=a.entries;out[7]=a.wins;out[8]=a.costs;out[9]=a.blocked;out[10]=a.failed;out[11]=a.maxMargin;return 0;}
extern "C" int micro_trades(void*ptr,int arm,double*out,int capacity){auto&a=static_cast<Engine*>(ptr)->a[arm];int n=std::min(capacity,a.closed);std::copy(a.trades.begin(),a.trades.begin()+n*12,out);return n;}
extern "C" void micro_destroy(void*ptr){delete static_cast<Engine*>(ptr);}
